    question: 'Iは、25年前に取得した土地（取得費不明）を6,000万円で譲渡した。譲渡費用として150万円を支出した場合の譲渡所得の金額に関する次の記述のうち、正しいものはどれか（3,000万円特別控除等の適用はないものとする）。',
